// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address caller, address newKeeper) public {
        vm.assume(caller != address(0));
        vm.assume(newKeeper != address(0));
        vm.assume(caller != c.owner());

        address initialKeeper = c.keeper();

        vm.prank(caller);
        try c.setKeeper(newKeeper) { } catch { }

        address finalKeeper = c.keeper();

        assertTrue(finalKeeper == initialKeeper);
    }
}
